import {groupById} from './model.mjs';
import {optionModel} from './timetable-options.mjs';
export function normalizeTimetableDraft(p){if(!p||p.version!==1)throw Error('Unsupported timetable backup.');for(const kind of ['days','periods','teachers','subjects','rooms','groups','activities']){if(!Array.isArray(p[kind])||p[kind].length>5000)throw Error('Invalid '+kind+' data.');for(const r of p[kind]){if(!r||typeof r.id!=='string'||! /^[A-Za-z0-9:_#.-]+$/.test(r.id)||['__proto__','constructor','prototype'].includes(r.id))throw Error('Invalid resource identifier.');r.name=String(r.name||r.label||r.id);if(['teachers','rooms','groups'].includes(kind))r.blocked||=[];if(kind==='groups')r.studentIds||=[];if(kind==='periods')r.label||=r.id;}}for(const g of p.groups){const canonical=groupById(g.id);if(canonical&&String(g.year)!==String(canonical.year))throw Error('The year of a linked MIS form cannot be changed.');}if(p.optionModels)for(const year of [10,11])if(p.optionModels[year])optionModel(p.optionModels[year]);p.constraints||={maxTeacherDaily:8};p.constraints.maxTeacherDaily??=8;p.notes=Array.isArray(p.notes)?p.notes.map(String):[];let cards=0;for(const a of p.activities){cards+=Number.isInteger(a.weeklyCount)&&a.weeklyCount>=0?a.weeklyCount:0;if(cards>10000)throw Error('Import up to 10,000 lesson cards in this planning prototype.');a.groupIds||=[];a.roomIds||=[];a.studentIds||=[...new Set(p.groups.filter(g=>a.groupIds.includes(g.id)).flatMap(g=>g.studentIds))];}return p;}
